/**
 * Sequence descriptive statistics inspired by TraMineR.
 * All functions accept wide-format (string | null)[][] data.
 */

/**
 * Collect all unique non-null states from data, sorted alphabetically.
 */
function collectStates(data: (string | null)[][]): string[] {
  const stateSet = new Set<string>();
  for (let i = 0; i < data.length; i++) {
    const seq = data[i]!;
    for (let j = 0; j < seq.length; j++) {
      const v = seq[j];
      if (v != null) stateSet.add(v);
    }
  }
  return Array.from(stateSet).sort();
}

/**
 * Find the maximum sequence length across all sequences.
 */
function maxLength(data: (string | null)[][]): number {
  let max = 0;
  for (let i = 0; i < data.length; i++) {
    if (data[i]!.length > max) max = data[i]!.length;
  }
  return max;
}

/**
 * State proportions at each time position (TraMineR seqstatd).
 * Ignores null values at each position.
 */
export function sequenceStateDistribution(data: (string | null)[][]): {
  proportions: number[][];
  counts: number[][];
  states: string[];
  nPositions: number;
} {
  const states = collectStates(data);
  const nPos = maxLength(data);
  const nStates = states.length;
  const stateIndex = new Map<string, number>();
  for (let s = 0; s < nStates; s++) {
    stateIndex.set(states[s]!, s);
  }

  // counts[pos][state]
  const counts: number[][] = [];
  for (let t = 0; t < nPos; t++) {
    counts.push(new Array(nStates).fill(0) as number[]);
  }

  for (let i = 0; i < data.length; i++) {
    const seq = data[i]!;
    for (let t = 0; t < seq.length; t++) {
      const v = seq[t];
      if (v != null) {
        const idx = stateIndex.get(v)!;
        const row = counts[t]!;
        row[idx] = (row[idx] ?? 0) + 1;
      }
    }
  }

  const proportions: number[][] = [];
  for (let t = 0; t < nPos; t++) {
    let totalNonNull = 0;
    for (let s = 0; s < nStates; s++) {
      totalNonNull += counts[t]![s]!;
    }
    const row: number[] = new Array(nStates);
    for (let s = 0; s < nStates; s++) {
      row[s] = totalNonNull > 0 ? counts[t]![s]! / totalNonNull : 0;
    }
    proportions.push(row);
  }

  return { proportions, counts, states, nPositions: nPos };
}

/**
 * Overall state frequencies across entire dataset (TraMineR seqstatf).
 * Counts each occurrence of each state across all positions.
 * Ignores null values.
 */
export function sequenceStateFrequencies(data: (string | null)[][]): {
  counts: number[];
  proportions: number[];
  states: string[];
  total: number;
} {
  const states = collectStates(data);
  const nStates = states.length;
  const stateIndex = new Map<string, number>();
  for (let s = 0; s < nStates; s++) {
    stateIndex.set(states[s]!, s);
  }

  const counts = new Array(nStates).fill(0) as number[];
  let total = 0;

  for (let i = 0; i < data.length; i++) {
    const seq = data[i]!;
    for (let j = 0; j < seq.length; j++) {
      const v = seq[j];
      if (v != null) {
        const ci = stateIndex.get(v)!;
        counts[ci] = (counts[ci] ?? 0) + 1;
        total++;
      }
    }
  }

  const proportions = new Array(nStates) as number[];
  for (let s = 0; s < nStates; s++) {
    proportions[s] = total > 0 ? counts[s]! / total : 0;
  }

  return { counts, proportions, states, total };
}

/**
 * Mean time (number of positions) spent in each state per sequence (TraMineR seqmeant).
 * Computes per-sequence count of each state, then takes mean and sd across sequences.
 * Uses sample sd (n-1) matching R's sd().
 * Ignores null values.
 */
export function meanTimeInState(data: (string | null)[][]): {
  meanTime: number[];
  sdTime: number[];
  states: string[];
} {
  const states = collectStates(data);
  const nStates = states.length;
  const n = data.length;
  const stateIndex = new Map<string, number>();
  for (let s = 0; s < nStates; s++) {
    stateIndex.set(states[s]!, s);
  }

  // perSeq[seq][state] = count of that state in that sequence
  const perSeq: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row = new Array(nStates).fill(0) as number[];
    const seq = data[i]!;
    for (let j = 0; j < seq.length; j++) {
      const v = seq[j];
      if (v != null) {
        const ri = stateIndex.get(v)!;
        row[ri] = (row[ri] ?? 0) + 1;
      }
    }
    perSeq.push(row);
  }

  const meanTime = new Array(nStates) as number[];
  const sdTime = new Array(nStates) as number[];

  for (let s = 0; s < nStates; s++) {
    if (n === 0) {
      meanTime[s] = 0;
      sdTime[s] = 0;
      continue;
    }
    let sum = 0;
    for (let i = 0; i < n; i++) {
      sum += perSeq[i]![s]!;
    }
    const mean = sum / n;
    meanTime[s] = mean;

    if (n <= 1) {
      sdTime[s] = NaN;
      continue;
    }
    let sumSq = 0;
    for (let i = 0; i < n; i++) {
      const diff = perSeq[i]![s]! - mean;
      sumSq += diff * diff;
    }
    sdTime[s] = Math.sqrt(sumSq / (n - 1));
  }

  return { meanTime, sdTime, states };
}

/**
 * Modal (most frequent) state at each position (TraMineR seqmodst).
 * Returns the state with highest frequency at each position, and its proportion.
 * Ties broken alphabetically (states are already sorted).
 */
export function modalSequence(data: (string | null)[][]): {
  states: string[];
  proportions: number[];
} {
  const dist = sequenceStateDistribution(data);
  const nPos = dist.nPositions;
  const allStates = dist.states;
  const nStates = allStates.length;

  const modalStates: string[] = new Array(nPos);
  const modalProportions: number[] = new Array(nPos);

  for (let t = 0; t < nPos; t++) {
    let maxCount = -1;
    let maxIdx = 0;
    for (let s = 0; s < nStates; s++) {
      if (dist.counts[t]![s]! > maxCount) {
        maxCount = dist.counts[t]![s]!;
        maxIdx = s;
      }
      // Ties: first state (alphabetically) wins since states are sorted
      // and we use strict > (not >=)
    }

    // Compute total non-null at this position
    let totalNonNull = 0;
    for (let s = 0; s < nStates; s++) {
      totalNonNull += dist.counts[t]![s]!;
    }

    if (totalNonNull > 0) {
      modalStates[t] = allStates[maxIdx]!;
      modalProportions[t] = maxCount / totalNonNull;
    } else {
      // No non-null values at this position
      modalStates[t] = '';
      modalProportions[t] = 0;
    }
  }

  return { states: modalStates, proportions: modalProportions };
}

/**
 * Shannon entropy at each position.
 * H = -sum(p_i * log2(p_i)) for p_i > 0.
 * Normalized by log2(nStates) so values are in [0, 1].
 * nStates = total number of unique states in the dataset (not just at that position).
 */
export function entropyProfile(data: (string | null)[][]): {
  entropy: number[];
  nPositions: number;
} {
  const dist = sequenceStateDistribution(data);
  const nPos = dist.nPositions;
  const nStates = dist.states.length;
  const logNStates = nStates > 1 ? Math.log2(nStates) : 0;

  const entropy: number[] = new Array(nPos);

  for (let t = 0; t < nPos; t++) {
    const props = dist.proportions[t]!;
    let h = 0;
    for (let s = 0; s < nStates; s++) {
      const p = props[s]!;
      if (p > 0) {
        h -= p * Math.log2(p);
      }
    }
    entropy[t] = logNStates > 0 ? h / logNStates : 0;
  }

  return { entropy, nPositions: nPos };
}

/**
 * Most frequent complete sequences ranked by count.
 * Sequences compared as JSON strings (with nulls stripped from the end).
 * Returns top N (default all).
 */
export function sequenceFrequencies(
  data: (string | null)[][],
  options?: { top?: number },
): { sequence: string[]; count: number; proportion: number }[] {
  const n = data.length;
  if (n === 0) return [];

  // Convert each sequence to canonical form: strip trailing nulls
  const canonical: string[][] = [];
  for (let i = 0; i < n; i++) {
    const seq = data[i]!;
    // Find last non-null index
    let lastNonNull = seq.length - 1;
    while (lastNonNull >= 0 && seq[lastNonNull] === null) {
      lastNonNull--;
    }
    const trimmed: string[] = [];
    for (let j = 0; j <= lastNonNull; j++) {
      trimmed.push(seq[j] ?? '');
    }
    canonical.push(trimmed);
  }

  // Build frequency map
  const freqMap = new Map<string, { sequence: string[]; count: number }>();
  for (let i = 0; i < n; i++) {
    const key = JSON.stringify(canonical[i]);
    const existing = freqMap.get(key);
    if (existing) {
      existing.count++;
    } else {
      freqMap.set(key, { sequence: canonical[i]!, count: 1 });
    }
  }

  // Sort descending by count, then alphabetically by key for stability
  const entries = Array.from(freqMap.entries());
  entries.sort((a, b) => {
    if (b[1].count !== a[1].count) return b[1].count - a[1].count;
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
  });

  const top = options?.top ?? entries.length;
  const results: { sequence: string[]; count: number; proportion: number }[] = [];
  for (let i = 0; i < Math.min(top, entries.length); i++) {
    const entry = entries[i]![1];
    results.push({
      sequence: entry.sequence,
      count: entry.count,
      proportion: entry.count / n,
    });
  }

  return results;
}
